import numpy as np

_LOC_EMPTY = {
    "float32": lambda n: np.zeros(n, dtype=np.float32),
    "float64": lambda n: np.zeros(n, dtype=np.float64),
    "int32": lambda n: np.zeros(n, dtype=np.int32),
    "int64": lambda n: np.zeros(n, dtype=np.int64),
}


class _HpcDataPair:
    """
    High Performance Computing (Data) Pair
    ======================================

    A pair of a HPC enabled data representation and a local representation.
    The synchronisation between these representations is *NOT* automatized.
    Such a pair might be used without any local representation.
    """

    @classmethod
    def transfer_loc2ref(cls, loc, ref):
        """transfer from loc to ref"""
        raise NotImplementedError("Subclass must implement this method")

    @classmethod
    def transfer_ref2loc(cls, ref, loc):
        """transfer from ref to loc"""
        raise NotImplementedError("Subclass must implement this method")

    @classmethod
    def empty_ref(cls, size, dtype):
        """create an empty reference object"""
        raise NotImplementedError("Subclass must implement this method")

    def __init__(self, size, dtype="real64"):
        self._size = size
        self._loc = None
        self._ref = None
        self._dtype = dtype
        self.init_ref()

    def init_ref(self):
        self._ref = self.__class__.empty_ref(self._size, dtype=self._dtype)
        return self

    def init_loc(self):
        self._loc = _LOC_EMPTY[self._dtype](self._size)
        return self

    def loc2ref(self):
        """transfer local to reference"""
        self.__class__.transfer_loc2ref(self._loc, self._ref)
        return self

    def ref2loc(self):
        """transfer reference to local"""
        self.__class__.transfer_ref2loc(self._ref, self._loc)
        return self


class ADAA:
    """combines multiple HPC pairs and provides auto sync"""

    def __init__(self, size):
        self._data_r = _HpcDataPair(size, dtype="real64")
        self._data_i = _HpcDataPair(size, dtype="real64")

        self._ref_ud = False
        self._loc_ud = False

        self._meta = {}
        self._meta["size"] = size
        self._has_loc = False

    def _init_loc(self):
        if not self._has_loc:
            self._data_r.init_loc()
            self._data_i.init_loc()
            self._has_loc = True
            self._loc_ud = True
            self._ref_ud = False
        return self

    def _loc_check(self):
        if self._has_loc:
            if not self._loc_ud:
                self.ref2loc()
        return self

    def _ref_check(self):
        if self._has_loc:
            if not self._ref_ud:
                self.loc2ref()
        return self

    def loc2ref(self):
        """transfer local to reference"""
        if self._has_loc:
            self._data_r.loc2ref()
            self._data_i.loc2ref()
        self._ref_ud = True
        return self

    def ref2loc(self):
        """transfer reference to local"""
        if self._has_loc:
            self._data_r.ref2loc()
            self._data_i.ref2loc()
            self._loc_ud = True
        return self

    def flag_ref(self):
        """flag ref for update"""
        self._ref_ud = False

    def flag_loc(self):
        """flag loc for update"""
        self._loc_ud = False

    @property
    def loc(self):
        """get the local representation"""
        self._init_loc()  # inits if loc is None
        self.ref2loc()
        return self._loc

    @loc.setter
    def loc(self, value):
        """set the local to a value"""
        self._init_loc()
        self._loc = value
        self.flag_ref()
        return self

    def ref(self, allow_write=False):
        """get the reference"""
        self._ref_check()
        if allow_write:
            self._loc_ud = False
        return self._ref


class ADAA:
    pass
